/** Standalone SVG strings (favicon, share image, email). */
const rects = (bars: Bar[], fill: string) => bars.map((b) => `<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" fill="${fill}"/>`).join("");

export function logoSvg({ background = LOGO_RED, fill = "#fff" }: { background?: string; fill?: string } = {}): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${LOGO_W} ${LOGO_H}">${background ? `<rect width="${LOGO_W}" height="${LOGO_H}" fill="${background}"/>` : ""}${rects([...BARS_LEFT, ...BARS_RIGHT, RULE], fill)}<path fill="${fill}" fill-rule="evenodd" d="${MARK_D}"/><path fill="${fill}" fill-rule="evenodd" d="${TAGLINE_D}"/></svg>`;
}

/** Square app icon: the SA monogram on brand red. */
export function iconSvg({ size = 512, radius = 0.22 }: { size?: number; radius?: number } = {}): string {
  const pad = MARK_BOX.w * 0.2;
  const side = MARK_BOX.w + pad * 2;
  const x = MARK_BOX.x - pad;
  const y = MARK_BOX.y + MARK_BOX.h / 2 - side / 2;
  const r = side * radius;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="${x} ${y} ${side} ${side}"><rect x="${x}" y="${y}" width="${side}" height="${side}" rx="${r}" fill="${LOGO_RED}"/><path fill="#fff" fill-rule="evenodd" d="${MARK_D}"/></svg>`;
}
